body:
While we're here, I think we should consider refactoring this method. At present, this embeds several side effects within an expression that calculates a return value. That makes it quite hard to understand (1) what state needs to be updated in each case, (2) separately, what effect that should have on the rest of the system. Something like the following will likely be longer but significantly clearer:

```rust
impl OpenDocumentHandle {
    fn close(&self, session: &mut Session, client: &Client) -> Result<bool> {
        let removed_document = session.index_mut().close_document(&self.key())?;

        let outcome = match self.file_path() {
            None => DocumentCloseOutcome::Cell,
            Some(AnySystemPath::System(path)) => {
                self.close_system_file(session, client, path, &removed_document)
            }
            Some(AnySystemPath::SystemVirtual(path)) => {
                self.close_virtual_file(session, path)
            }
        };

        let should_clear_diagnostics = match outcome {
            DocumentCloseOutcome::Cell | DocumentCloseOutcome::Virtual => true,
            DocumentCloseOutcome::System { path, deleted } => {
                deleted
                    || session.workspaces().for_path(path).is_none()
                    || session.global_settings().diagnostic_mode().is_open_files_only()
            }
        };

        session.bump_revision();
        Ok(should_clear_diagnostics)
    }
}

enum DocumentCloseOutcome<'a> {
    Cell,
    Virtual,
    System { path: &'a SystemPath, deleted: bool },
}
```

