+/// import re
+///
+/// re.match(pattern, string)
+/// ```
+///
+/// A pattern stored in a function-local variable that is read once is equivalent:
+/// ```python
+/// import re
+///
+///
+/// def is_static(arg):
+///     pattern = re.compile(r"^static pattern$")
+///     return pattern.match(arg)
+/// ```
+///
